```bash
sed -i '/func (pq \*PriorityQueue) Dispose(/,/}/c\
// Dispose will prevent any further reads/writes to this queue
// and frees available resources, returning any items that were in the queue.
func (pq *PriorityQueue) Dispose() []interface{} {
	pq.lock.Lock()
	defer pq.lock.Unlock()

	pq.disposeLock.Lock()
	defer pq.disposeLock.Unlock()

	pq.disposed = true
	for _, waiter := range pq.waiters {
		waiter.response.Add(1)
		waiter.ready <- true
	}

	// Collect items to return
	items := make([]interface{}, len(pq.items))
	for i, item := range pq.items {
		items[i] = item
	}

	pq.items = nil
	pq.waiters = nil
	pq.itemMap = nil

	return items
}' queue/priority_queue.go
```

