package queue

import (
	"testing"
	"time"
)

// Test that Queue implements QueueInterface
var _ QueueInterface = &Queue{}

// Test that PriorityQueue implements QueueInterface
var _ QueueInterface = &PriorityQueue{}

// Mock item for testing PriorityQueue
type mockItem int

func (mi mockItem) Compare(other Item) int {
	otherMi := other.(mockItem)
	if mi > otherMi {
		return 1
	} else if mi < otherMi {
		return -1
	}
	return 0
}

func TestUnifiedInterface(t *testing.T) {
	// Test regular queue
	var q QueueInterface = New(10)

	// Test basic operations
	if q.Empty() != true {
		t.Error("Expected queue to be empty")
	}

	if q.Len() != 0 {
		t.Error("Expected queue length to be 0")
	}

	if q.Disposed() != false {
		t.Error("Expected queue to not be disposed")
	}

	// Test Peek on empty queue
	_, err := q.Peek()
	if err != ErrEmptyQueue {
		t.Error("Expected ErrEmptyQueue when peeking empty queue")
	}

	// Test putting and getting items
	q.Put("item1", "item2")

	if q.Empty() != false {
		t.Error("Expected queue to not be empty")
	}

	if q.Len() != 2 {
		t.Errorf("Expected queue length to be 2, got %d", q.Len())
	}

	// Test Peek on non-empty queue
	item, err := q.Peek()
	if err != nil {
		t.Errorf("Unexpected error when peeking: %v", err)
	}
	if item != "item1" {
		t.Errorf("Expected peek to return 'item1', got %v", item)
	}

	// Test Dispose
	items := q.Dispose()
	if len(items) != 2 {
		t.Errorf("Expected 2 items from dispose, got %d", len(items))
	}

	if q.Disposed() != true {
		t.Error("Expected queue to be disposed")
	}

	// Test priority queue
	var pq QueueInterface = NewPriorityQueue(10, false)

	// Test basic operations
	if pq.Empty() != true {
		t.Error("Expected priority queue to be empty")
	}

	if pq.Len() != 0 {
		t.Error("Expected priority queue length to be 0")
	}

	if pq.Disposed() != false {
		t.Error("Expected priority queue to not be disposed")
	}

	// Test Peek on empty queue
	_, err = pq.Peek()
	if err != ErrEmptyQueue {
		t.Error("Expected ErrEmptyQueue when peeking empty priority queue")
	}

	// Test putting and getting items
	pq.Put(mockItem(2), mockItem(1))

	if pq.Empty() != false {
		t.Error("Expected priority queue to not be empty")
	}

	if pq.Len() != 2 {
		t.Errorf("Expected priority queue length to be 2, got %d", pq.Len())
	}

	// Test Peek on non-empty queue
	item, err = pq.Peek()
	if err != nil {
		t.Errorf("Unexpected error when peeking priority queue: %v", err)
	}
	if item.(mockItem) != mockItem(1) {
		t.Errorf("Expected peek to return mockItem(1), got %v", item)
	}

	// Test Dispose
	items = pq.Dispose()
	if len(items) != 2 {
		t.Errorf("Expected 2 items from priority queue dispose, got %d", len(items))
	}

	if pq.Disposed() != true {
		t.Error("Expected priority queue to be disposed")
	}
}
